create or replace function public.ifund_create_auth_profile() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.ifund_profiles (id, display_name) values (new.id, nullif(left(coalesce(new.raw_user_meta_data ->> 'display_name', ''), 120), '')) on conflict (id) do nothing; return new; end; $$; revoke all on function public.ifund_create_auth_profile() from public; drop trigger if exists ifund_auth_profile_created on auth.users; create trigger ifund_auth_profile_created after insert on auth.users for each row execute function public.ifund_create_auth_profile(); insert into public.ifund_profiles (id,display_name) select u.id,nullif(left(coalesce(u.raw_user_meta_data ->> 'display_name',''),120),'') from auth.users u on conflict (id) do nothing;